using MediatR; using Tooba.BuildingBlocks; using Tooba.BuildingBlocks.Results; using Tooba.Promotion.Application.Errors; using Tooba.Promotion.Application.Models; using Tooba.Promotion.Application.Ports;
namespace Tooba.Promotion.Application.Commands.CreateSellerPromotion;
public sealed record CreateSellerPromotionCommand(Guid SellerPartyId,PromotionMutationInput Input):IRequest<Result<PromotionReference>>;
public sealed class CreateSellerPromotionCommandHandler(IPromotionDirectory promotions,IClock clock):IRequestHandler<CreateSellerPromotionCommand,Result<PromotionReference>>{public Task<Result<PromotionReference>> Handle(CreateSellerPromotionCommand r,CancellationToken ct)=>PromotionExceptionMapper.TryAsync(async()=>{var p=PromotionMutationNormalizer.Normalize(r.Input,clock);return await promotions.CreateForSellerAsync(null,r.SellerPartyId,p.Name,p.EffectiveFrom,p.EffectiveTo,p.DiscountKind,p.PercentageRate,p.FixedAmount,p.FixedAmountCurrency,p.CouponCode,p.MinimumSubtotal,ct);});}
